// tests/unit/payment-link-token.test.ts
// Pure-function tests for the payment-link token helper. Tokens are
// generated by ops from /ops/billing ("send payment link to driver"),
// delivered via SMS, then walked by the driver to /pay/<token> which
// redirects them to /driver/payments pre-highlighting the agreement.
//
// The pure layer is small: token generation + expiry checks. The DB
// stores it; the action generates it; the page verifies it.

import { describe, expect, it } from 'vitest';
import {
  isPaymentTokenExpired,
  isPaymentTokenUsable,
  generatePaymentLinkToken,
  PAYMENT_LINK_TTL_HOURS,
} from '@/lib/billing/payment-link-token';

const NOW = new Date('2026-09-15T12:00:00Z');

describe('generatePaymentLinkToken', () => {
  it('produces a URL-safe string of length 32', () => {
    const t = generatePaymentLinkToken();
    expect(t).toMatch(/^[A-Za-z0-9_-]{32}$/);
  });
  it('produces a different value on each call (24 bits minimum of entropy)', () => {
    const set = new Set<string>();
    for (let i = 0; i < 20; i++) set.add(generatePaymentLinkToken());
    expect(set.size).toBe(20);
  });
});

describe('PAYMENT_LINK_TTL_HOURS', () => {
  it('is 72 (a week\'s worth of reminder windows)', () => {
    expect(PAYMENT_LINK_TTL_HOURS).toBe(72);
  });
});

describe('isPaymentTokenExpired', () => {
  it('returns false for a future expiry', () => {
    const exp = new Date(NOW.getTime() + 60 * 60 * 1000);
    expect(isPaymentTokenExpired(exp, NOW)).toBe(false);
  });
  it('returns true for a past expiry', () => {
    const exp = new Date(NOW.getTime() - 1000);
    expect(isPaymentTokenExpired(exp, NOW)).toBe(true);
  });
  it('returns true at the exact boundary', () => {
    const exp = new Date(NOW.getTime());
    expect(isPaymentTokenExpired(exp, NOW)).toBe(true);
  });
});

describe('isPaymentTokenUsable', () => {
  it('is usable when not expired and not used', () => {
    const exp = new Date(NOW.getTime() + 60 * 60 * 1000);
    expect(isPaymentTokenUsable(exp, null, NOW)).toBe(true);
  });
  it('is not usable when expired', () => {
    const exp = new Date(NOW.getTime() - 1000);
    expect(isPaymentTokenUsable(exp, null, NOW)).toBe(false);
  });
  it('is not usable when usedAt is set (single-use)', () => {
    const exp = new Date(NOW.getTime() + 60 * 60 * 1000);
    expect(isPaymentTokenUsable(exp, new Date(NOW.getTime() - 30_000), NOW)).toBe(false);
  });
});